/* Bridges — native shell.
 *
 * Same five destinations as the web app: Learn, Study, Practice, Immerse, Search.
 * The learning data, the scheduler and the icon set are imported from core/ and
 * native/assets/data.json, both generated by the same Python pipeline, so the two
 * platforms cannot drift apart on content.
 */

import React from "react";
import { StatusBar } from "expo-status-bar";
import { useColorScheme } from "react-native";
import { SafeAreaProvider } from "react-native-safe-area-context";
import { NavigationContainer, DefaultTheme, DarkTheme } from "@react-navigation/native";
import { createNativeStackNavigator } from "@react-navigation/native-stack";
import { createBottomTabNavigator } from "@react-navigation/bottom-tabs";
import Svg, { Path, Rect, Circle } from "react-native-svg";

import { SessionProvider, useSession } from "./src/session";
import { light, dark } from "./src/theme";
import { Loading } from "./src/ui";
import Learn from "./src/screens/Learn";
import Search from "./src/screens/Search";
import { UnitScreen, LessonScreen } from "./src/screens/Unit";
import { Immerse, Video, Gate, NotPorted } from "./src/screens/Misc";

const Tabs = createBottomTabNavigator();
const Stack = createNativeStackNavigator();

const icon = (d) => ({ color, size }) => (
  <Svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color}
       strokeWidth={1.9} strokeLinecap="round" strokeLinejoin="round">
    <Path d={d} />
  </Svg>
);

const LearnIcon = icon("M4 19V6a2 2 0 0 1 2-2h5v15H6a2 2 0 0 0-2 2zM20 19V6a2 2 0 0 0-2-2h-5v15h5a2 2 0 0 1 2 2z");
const StudyIcon = icon("M3 6h14v12H3zM7 3h14v13");
const PracticeIcon = icon("M6 9v6M18 9v6M4 11v2M20 11v2M8 7v10M16 7v10M8 12h8");
const ImmerseIcon = icon("M3 5h18v14H3zm8 4.5 4 2.5-4 2.5z");
const SearchIcon = icon("M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zm9 16-3.5-3.5");

function Study() {
  return (
    <NotPorted
      title="Study"
      detail={"Flashcards with the four Anki buttons and FSRS scheduling. The " +
              "scheduler itself is already shared with this app — core/fsrs.js — but " +
              "the card runner and the set picker are still web-only."}
      web="/#/practice"
    />
  );
}

function Practice() {
  return (
    <NotPorted
      title="Practice"
      detail={"Six grammar drills: cases, aspect pairs, agreement, conjugation, " +
              "stress and grammar rules, each able to pull up the table that answers " +
              "it. The generators read the same paradigm data this app has loaded; " +
              "what is missing is the native exercise runner."}
      web="/#/drills"
    />
  );
}

function LearnStack() {
  return (
    <Stack.Navigator screenOptions={{ headerShown: true }}>
      <Stack.Screen name="Path" component={Learn} options={{ title: "Learn" }} />
      <Stack.Screen name="Unit" component={UnitScreen}
                    options={{ title: "Unit" }} />
      <Stack.Screen name="Lesson" component={LessonScreen}
                    options={{ title: "Lesson" }} />
      <Stack.Screen name="Video" component={Video} options={{ title: "Video" }} />
      <Stack.Screen name="Run" component={Practice} options={{ title: "Lesson" }} />
    </Stack.Navigator>
  );
}

function ImmerseStack() {
  return (
    <Stack.Navigator>
      <Stack.Screen name="Episodes" component={Immerse} options={{ title: "Immerse" }} />
      <Stack.Screen name="Video" component={Video} options={{ title: "Video" }} />
    </Stack.Navigator>
  );
}

function Shell() {
  const { ready, account } = useSession();
  if (!ready) return <Loading />;
  if (!account) return <Gate />;

  return (
    <Tabs.Navigator screenOptions={{ headerShown: false }}>
      <Tabs.Screen name="Learn" component={LearnStack}
                   options={{ tabBarIcon: LearnIcon }} />
      <Tabs.Screen name="Study" component={Study}
                   options={{ tabBarIcon: StudyIcon }} />
      <Tabs.Screen name="Practice" component={Practice}
                   options={{ tabBarIcon: PracticeIcon }} />
      <Tabs.Screen name="Immerse" component={ImmerseStack}
                   options={{ tabBarIcon: ImmerseIcon }} />
      <Tabs.Screen name="Search" component={Search}
                   options={{ tabBarIcon: SearchIcon }} />
    </Tabs.Navigator>
  );
}

export default function App() {
  const scheme = useColorScheme();
  const p = scheme === "light" ? light : dark;
  const navTheme = {
    ...(scheme === "light" ? DefaultTheme : DarkTheme),
    colors: {
      ...(scheme === "light" ? DefaultTheme : DarkTheme).colors,
      background: p.bg, card: p.surface, text: p.ink, border: p.line, primary: p.brand,
    },
  };

  return (
    <SafeAreaProvider>
      <SessionProvider>
        <NavigationContainer theme={navTheme}>
          <Shell />
          <StatusBar style={scheme === "light" ? "dark" : "light"} />
        </NavigationContainer>
      </SessionProvider>
    </SafeAreaProvider>
  );
}
